    slug: "planetary-science-small-body-exploration",
    title: { zh: "行星科学与小天体探测", en: "Planetary Science & Small-Body Exploration" },
    qfocus: { zh: "一份未经大气烧蚀与地表风化的原始样品，能给出哪些陨石永远无法给出的太阳系初始条件？", en: "What initial conditions of the solar system can a sample untouched by atmospheric ablation and terrestrial weathering reveal that meteorites never can?" },
    domain: "交叉",
    cluster: { code: "C18", zh: "大众空间科学", en: "Citizen space science" },
    scores: [4, 4, 3, 2, 2, 1, 5, 4, 4],
    citation: {
      url: "https://arxiv.org/abs/2604.22182",
      title: "The science from asteroid sample return missions",
      venue: "Contemporary Physics (arXiv)",
      year: 2026,
    },
    brief: { zh: "以轨道器测绘选点、着陆器原位取样、密封返回舱送回实验室，把龙宫这类返回样品与 Ivuna 型碳质陨石逐项比对，分离母体信号与地球污染，并全程守住行星保护的防污染链。", en: "Select sites by orbiter mapping, sample in situ with a lander, return sealed capsules to the laboratory, and compare returned material such as Ryugu item by item against Ivuna-type carbonaceous meteorites to separate parent-body signal from terrestrial contamination — holding the planetary-protection chain intact throughout." },
    literature: [
      { title: "Importance of asteroid sample return", venue: "Nature Geoscience", year: 2023, url: "https://www.nature.com/articles/s41561-023-01295-z" },
      { title: "Samples returned from the asteroid Ryugu are similar to Ivuna-type carbonaceous meteorites", venue: "Science", year: 2022, url: "https://www.science.org/doi/10.1126/science.abn7850" },
    ],
    depth: {
      overview: { zh: "行星科学把地质学方法延伸到地外天体：轨道器测绘、着陆器原位、采样返回，把太阳系最原始的物质带回实验室。隼鸟2 与 OSIRIS-REx 之后，龙宫样品被证明与 Ivuna 型碳质陨石相似，第一次让未经地球改写的档案与陨石库直接对照。", en: "Planetary science extends geological method to other bodies: orbiters map, landers work in situ, and sample return brings the solar system's most primitive matter into the laboratory. After Hayabusa2 and OSIRIS-REx, Ryugu material was shown to resemble Ivuna-type carbonaceous meteorites — the first direct confrontation between an archive unrewritten by Earth and the meteorite collections." },
      whyMatters: { zh: "太阳系形成的初始条件写在最原始的碳质物质里，而落到地面的陨石都经过烧蚀与风化；采样返回是唯一干净的读法，代价是十余年周期与一次性风险。", en: "The initial conditions of solar-system formation are written in the most primitive carbonaceous matter, yet every meteorite on the ground has passed through ablation and weathering. Sample return is the only clean reading, at the price of a decade-plus cycle and one-shot risk." },
      ifAnswered: { zh: "庞大的陨石库可以被少量原始样品重新校准，太阳系早期的挥发分与有机物清单从推断变成实测。", en: "Vast meteorite collections could be recalibrated against a small quantity of pristine material, turning the early solar system's volatile and organic inventory from inference into measurement." },
      approaches: [
        { zh: "用轨道器的全球测绘与热惯量图选取能代表母体的取样点。", en: "Use orbiter global mapping and thermal-inertia imagery to choose sampling sites representative of the parent body." },
        { zh: "把返回样品与 Ivuna 型碳质陨石放进同一套矿物学与同位素比对。", en: "Run returned samples and Ivuna-type carbonaceous meteorites through one common mineralogical and isotopic comparison." },
        { zh: "以全程密封与专用洁净舱执行行星保护，逐环节留存污染本底样本。", en: "Enforce planetary protection through end-to-end sealing and dedicated clean facilities, retaining contamination-blank samples at every step." },
      ],
      barrier: { zh: "任务周期十余年且不可重来，防污染链上任何一处密封失败都会一次性毁掉样品；等到发现问题时，重做的代价是又一个十年。", en: "The mission cycle runs over a decade and cannot be rerun, and a single seal failure anywhere in the contamination chain destroys the sample outright. By the time the problem surfaces, the cost of redoing it is another decade." },
      subQuestions: [
        { zh: "龙宫样品与 Ivuna 型陨石之间的差异，有多少来自地球风化，有多少来自母体本身？", en: "How much of the difference between Ryugu material and Ivuna-type meteorites comes from terrestrial weathering, and how much from the parent body itself?" },
        { zh: "取样点的局部代表性该如何评估，单点样品能不能外推到整个小天体？", en: "How should the local representativeness of a sampling site be assessed, and can a single-site sample be extrapolated to the whole body?" },
        { zh: "洁净链的污染本底要压到什么量级，有机物检测的结论才不被地球背景吞没？", en: "To what level must the contamination blank be driven before organic-detection results stop being swamped by terrestrial background?" },
      ],
    },
