    atlasN: 1727,
    slug: "patient-clinician-co-prioritization-unanswered-research",
    title: { zh: "患者—临床共同确定未答研究问题", en: "Patient–Clinician Co-Prioritization of Unanswered Research Questions" },
    qfocus: { zh: "患者与临床人员共同排出的研究优先级，是对真实需求的测量，还是招募方式与会场措辞的产物？", en: "Is a research priority list co-ranked by patients and clinicians a measurement of real need, or an artifact of who was recruited and how the workshop worded things?" },
    domain: "交叉",
    cluster: { code: "C34", zh: "无知测绘·盲区科学", en: "Mapping ignorance & blind spots" },
    scores: [5, 4, 2, 4, 5, 5, 3, 2, 4],
    citation: {
      url: "https://doi.org/10.1016/S2215-0366(18)30296-7",
      title: "Identifying research priorities for digital technology in mental health care: results of the James Lind Alliance Priority Setting Partnership",
      venue: "The Lancet Psychiatry",
      year: 2018,
    },
    brief: { zh: "按 James Lind Alliance 流程汇集患者、照护者与临床人员提出的不确定性，逐条做证据核查剔除已被回答者，合并去重后在共识会议上排出前十，并公开每一步的筛除记录与参与者构成。", en: "Follow the James Lind Alliance process: gather uncertainties submitted by patients, carers and clinicians, evidence-check each one to remove those already answered, merge duplicates, rank a top ten at a consensus workshop, and publish the removal log and participant composition at every step." },
    literature: [
      { title: "Patient- and public-driven health research: a model of co-leadership and partnership in research priority setting using a modified James Lind Alliance approach", venue: "Journal of Clinical Epidemiology", year: 2025, url: "https://doi.org/10.1016/j.jclinepi.2025.111731" },
      { title: "The top 10 priorities in adults living with type 1 diabetes in Ireland and the United Kingdom – A James Lind Alliance priority setting partnership", venue: "Diabetic Medicine", year: 2024, url: "https://doi.org/10.1111/dme.15429" },
    ],
    depth: {
      overview: { zh: "研究议程通常由研究者与资助方设定，未答问题清单因此偏向可发表的方向。James Lind Alliance 的优先排序伙伴关系把患者、照护者与临床人员放进同一条汇集—证据核查—共识排序的流程：Lancet Psychiatry 用它排出数字心理健康的未答问题，Journal of Clinical Epidemiology 进一步把患者与公众推到共同领导与证据核查的位置。", en: "Research agendas are usually set by investigators and funders, so lists of unanswered questions tilt toward what is publishable. James Lind Alliance priority setting partnerships put patients, carers and clinicians into one pipeline of gathering, evidence-checking and consensus ranking: The Lancet Psychiatry used it to rank unanswered questions in digital mental health, and the Journal of Clinical Epidemiology pushed patients and the public further, into co-leadership and evidence-checking roles." },
      whyMatters: { zh: "临床研究的浪费有很大一部分来自回答了没人需要回答的问题，共同排序把这一环打开。但形式上的平等席位不自动等于实际话语权，会议措辞与谁被招募都会改写名次。", en: "A large share of waste in clinical research comes from answering questions nobody needed answered, and co-prioritization opens that link. But formally equal seats do not automatically mean equal power, and both workshop wording and recruitment rewrite the ranking." },
      ifAnswered: { zh: "资助机构可以对着一份被患者认领过的问题清单直接拨款，跨年份的名次变化也能被读作需求变化而非参会者更替。", en: "Funders could allocate against a question list patients have actually claimed, and shifts in rank across years could be read as changing need rather than changing attendees." },
      approaches: [
        { zh: "按 JLA 流程做全国征集，把每条提交与系统综述比对，剔除已被现有证据回答的问题。", en: "Run a national call under the JLA process, check each submission against systematic reviews, and remove questions already answered by existing evidence." },
        { zh: "像 Diabetic Medicine 的 1 型糖尿病伙伴关系那样，分开统计患者、照护者与临床人员的排序差异。", en: "As in the Diabetic Medicine type 1 diabetes partnership, report the rankings of patients, carers and clinicians separately and compare the divergence." },
        { zh: "公开去重与合并的全部中间记录，让第三方能重放从原始提交到前十的每一步。", en: "Publish the full intermediate record of deduplication and merging so a third party can replay every step from raw submissions to the final ten." },
      ],
      barrier: { zh: "参与者是自我选择的：疾病阶段、国家与招募渠道决定了谁走进排序会议，而名次对这一构成极其敏感，无法靠事后加权补救。", en: "Participants self-select: disease stage, country and recruitment channel decide who reaches the ranking workshop, and the ranking is acutely sensitive to that composition in a way post-hoc weighting cannot repair." },
      subQuestions: [
        { zh: "同一疾病在不同国家重做优先排序时，前十的重合度有多高，差异来自需求还是医疗体系？", en: "When the same condition is re-prioritized in another country, how much does the top ten overlap, and does the difference come from need or from the health system?" },
        { zh: "把患者从参与者升为共同领导，是否真的改变了最终名次，而不只是改变了署名？", en: "Does elevating patients from participants to co-leaders actually change the final ranking, or only the authorship line?" },
        { zh: "进入前十的问题在随后数年里有多大比例真正获得资助并被回答，落空者有何共同特征？", en: "What fraction of top-ten questions actually attract funding and get answered in the following years, and what do the unfunded ones have in common?" },
      ],
    },
